def transform(g):
    import collections
    h,w=len(g),len(g[0])
    cnt=collections.Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    sep_r=[i for i in range(h) if len(set(g[i]))==1 and g[i][0]!=bg]
    sep_c=[j for j in range(w) if len({g[i][j] for i in range(h)})==1 and g[0][j]!=bg]
    def runs(n,seps):
        out=[];s=0
        for i in sorted(seps)+[n]:
            if i>s: out.append((s,i))
            s=i+1
        return out
    rr=runs(h,sep_r); cc=runs(w,sep_c)
    # pattern block: the block not uniformly bg
    pat=None; ptop=pbot=pl=pr=0
    for (r0,r1) in rr:
        for (c0,c1) in cc:
            blk=[g[i][c0:c1] for i in range(r0,r1)]
            if any(x!=bg for row in blk for x in row):
                pat=blk; ptop,pbot,pl,pr=r0,r1,c0,c1
    ph,pw=len(pat),len(pat[0])
    out=[r[:] for r in g]
    for (r0,r1) in rr:
        for (c0,c1) in cc:
            blk=[g[i][c0:c1] for i in range(r0,r1)]
            if all(x==bg for row in blk for x in row):
                for i in range(r0,r1):
                    for j in range(c0,c1):
                        out[i][j]=pat[(i-r0)%ph][(j-c0)%pw]
    return out
